def solve(**kwargs):
    import time
    import random

    start_time = time.time()
    deadline = start_time + 8.7

    n = int(kwargs.get("num_planes", 0))
    m = max(1, int(kwargs.get("num_runways", 1)))
    planes = kwargs["planes"]
    sep = kwargs["separation"]

    E = [float(p["earliest"]) for p in planes]
    T = [float(p["target"]) for p in planes]
    L = [float(p["latest"]) for p in planes]
    PE = [float(p.get("penalty_early", 1.0)) for p in planes]
    PL = [float(p.get("penalty_late", 1.0)) for p in planes]

    def schedule_order(order):
        """Return ({plane_id0: time}, cost) for a fixed runway order, or (None, inf)."""
        k = len(order)
        if k == 0:
            return {}, 0.0

        earliest_feasible = [0.0] * k
        for pos, pid in enumerate(order):
            if pos == 0:
                val = E[pid]
            else:
                prev = order[pos - 1]
                val = max(E[pid], earliest_feasible[pos - 1] + float(sep[prev][pid]))
            if val > L[pid] + 1e-7:
                return None, float("inf")
            earliest_feasible[pos] = val

        latest_feasible = [0.0] * k
        for pos in range(k - 1, -1, -1):
            pid = order[pos]
            if pos == k - 1:
                val = L[pid]
            else:
                nxt = order[pos + 1]
                val = min(L[pid], latest_feasible[pos + 1] - float(sep[pid][nxt]))
            if val + 1e-7 < earliest_feasible[pos]:
                return None, float("inf")
            latest_feasible[pos] = val

        times_list = [0.0] * k
        cost = 0.0
        next_time = None
        next_pid = None

        for pos in range(k - 1, -1, -1):
            pid = order[pos]
            upper = latest_feasible[pos]
            if next_time is not None:
                upper = min(upper, next_time - float(sep[pid][next_pid]))

            if upper + 1e-7 < earliest_feasible[pos]:
                return None, float("inf")

            t = T[pid]
            if t < earliest_feasible[pos]:
                t = earliest_feasible[pos]
            elif t > upper:
                t = upper

            times_list[pos] = t

            if t < T[pid]:
                cost += (T[pid] - t) * PE[pid]
            else:
                cost += (t - T[pid]) * PL[pid]

            next_time = t
            next_pid = pid

        return {order[i]: times_list[i] for i in range(k)}, cost

    def eval_solution(orders):
        all_times = {}
        total_cost = 0.0
        for order in orders:
            td, c = schedule_order(order)
            if td is None:
                return None, float("inf")
            all_times.update(td)
            total_cost += c
        if len(all_times) != n:
            return None, float("inf")
        return all_times, total_cost

    def build_with_order(plane_order):
        orders = [[] for _ in range(m)]
        runway_costs = [0.0] * m

        for pid in plane_order:
            if time.time() > deadline:
                return None, float("inf")

            best = None
            best_key = None

            for r in range(m):
                base = orders[r]
                for pos in range(len(base) + 1):
                    cand = base[:pos] + [pid] + base[pos:]
                    _, c = schedule_order(cand)
                    if c == float("inf"):
                        continue

                    delta = c - runway_costs[r]
                    key = (delta, c, len(base), r, pos)
                    if best_key is None or key < best_key:
                        best_key = key
                        best = (r, cand, c)

            if best is None:
                return None, float("inf")

            r, cand, c = best
            orders[r] = cand
            runway_costs[r] = c

        times, cost = eval_solution(orders)
        if times is None:
            return None, float("inf")
        return (orders, times), cost

    indices = list(range(n))

    candidate_orders = [
        sorted(indices, key=lambda i: (T[i], E[i], L[i])),
        sorted(indices, key=lambda i: (L[i], T[i], E[i])),
        sorted(indices, key=lambda i: (E[i], T[i], L[i])),
        sorted(indices, key=lambda i: (L[i] - E[i], T[i])),
        sorted(indices, key=lambda i: (T[i] - E[i], L[i])),
        sorted(indices, key=lambda i: (-(PE[i] + PL[i]), T[i])),
    ]

    best_sol = None
    best_cost = float("inf")

    for order in candidate_orders:
        if time.time() > deadline:
            break
        sol, cost = build_with_order(order)
        if sol is not None and cost < best_cost:
            best_sol = sol
            best_cost = cost

    rng = random.Random(12345)
    base = sorted(indices, key=lambda i: T[i])

    while time.time() < deadline and n <= 120:
        noisy = base[:]
        noisy.sort(
            key=lambda i: (
                T[i] + rng.uniform(-1.0, 1.0) * max(1.0, 0.15 * (L[i] - E[i])),
                L[i],
            )
        )
        sol, cost = build_with_order(noisy)
        if sol is not None and cost < best_cost:
            best_sol = sol
            best_cost = cost

    if best_sol is None:
        orders = [[] for _ in range(m)]
        costs = [0.0] * m

        for pid in sorted(indices, key=lambda i: (E[i], L[i], T[i])):
            best = None
            for r in range(m):
                cand = orders[r] + [pid]
                _, c = schedule_order(cand)
                if c < float("inf"):
                    key = (c - costs[r], len(orders[r]), r)
                    if best is None or key < best[0]:
                        best = (key, r, cand, c)

            if best is not None:
                _, r, cand, c = best
                orders[r] = cand
                costs[r] = c
            else:
                r = min(range(m), key=lambda x: len(orders[x]))
                orders[r].append(pid)

        times, _ = eval_solution(orders)
        if times is not None:
            best_sol = (orders, times)

    schedule = {}

    if best_sol is not None:
        orders, times = best_sol
        runway_of = {}
        for r, order in enumerate(orders, start=1):
            for pid in order:
                runway_of[pid] = r

        for pid in range(n):
            schedule[pid + 1] = {
                "landing_time": float(times.get(pid, max(E[pid], min(T[pid], L[pid])))),
                "runway": int(runway_of.get(pid, 1)),
            }
    else:
        for pid in range(n):
            schedule[pid + 1] = {
                "landing_time": float(max(E[pid], min(T[pid], L[pid]))),
                "runway": int((pid % m) + 1),
            }

    return {"schedule": schedule}

task_solution_map.assignment_problem:
def solve(**kwargs):
    """
    Solves an instance of the Assignment Problem.

    Input kwargs:
      - n: int
      - cost_matrix: 2D list-like or numpy.ndarray with shape (n, n)

    Returns:
      dict with:
        - "total_cost": minimal/heuristic total assignment cost
        - "assignment": list of 1-indexed (item, agent) tuples
    """
    n = kwargs["n"]
    cost_matrix = kwargs["cost_matrix"]

    if n <= 0:
        return {"total_cost": 0, "assignment": []}

    def _py_scalar(x):
        try:
            return x.item()
        except AttributeError:
            return x

    def hungarian(cm, n):
        # 1-indexed Hungarian algorithm for square minimization.
        u = [0] * (n + 1)
        v = [0] * (n + 1)
        p = [0] * (n + 1)
        way = [0] * (n + 1)

        inf = float("inf")

        for i in range(1, n + 1):
            p[0] = i
            j0 = 0
            minv = [inf] * (n + 1)
            used = [False] * (n + 1)

            while True:
                used[j0] = True
                i0 = p[j0]
                row = cm[i0 - 1]
                delta = inf
                j1 = 0

                ui0 = u[i0]
                for j in range(1, n + 1):
                    if not used[j]:
                        cur = row[j - 1] - ui0 - v[j]
                        if cur < minv[j]:
                            minv[j] = cur
                            way[j] = j0
                        if minv[j] < delta:
                            delta = minv[j]
                            j1 = j

                for j in range(0, n + 1):
                    if used[j]:
                        u[p[j]] += delta
                        v[j] -= delta
                    else:
                        minv[j] -= delta

                j0 = j1
                if p[j0] == 0:
                    break

            while True:
                j1 = way[j0]
                p[j0] = p[j1]
                j0 = j1
                if j0 == 0:
                    break

        row_to_col = [0] * n
        for j in range(1, n + 1):
            if p[j] != 0:
                row_to_col[p[j] - 1] = j - 1

        assignment = []
        total = 0
        for i, j in enumerate(row_to_col):
            assignment.append((i + 1, j + 1))
            total += _py_scalar(cm[i][j])

        return {"total_cost": _py_scalar(total), "assignment": assignment}

    def greedy_assignment(cm, n):
        # Regret-ordered greedy heuristic, O(n^2).
        row_info = []

        for i in range(n):
            row = cm[i]
            best_j = 0
            best = row[0]
            second = float("inf")

            for j in range(1, n):
                c = row[j]
                if c < best:
                    second = best
                    best = c
                    best_j = j
                elif c < second:
                    second = c

            regret = second - best
            row_info.append((regret, i, best_j))

        row_info.sort(reverse=True)

        used = [False] * n
        row_to_col = [-1] * n

        for _, i, best_j in row_info:
            if not used[best_j]:
                chosen = best_j
            else:
                row = cm[i]
                chosen = -1
                best_free_cost = None

                for j in range(n):
                    if not used[j]:
                        c = row[j]
                        if chosen < 0 or c < best_free_cost:
                            chosen = j
                            best_free_cost = c

            row_to_col[i] = chosen
            used[chosen] = True

        assignment = []
        total = 0
        for i, j in enumerate(row_to_col):
            assignment.append((i + 1, j + 1))
            total += _py_scalar(cm[i][j])

        return {"total_cost": _py_scalar(total), "assignment": assignment}

    # Exact for small/medium instances; fast feasible solution for large ones.
    if n <= 450:
        return hungarian(cost_matrix, n)
    return greedy_assignment(cost_matrix, n)

task_solution_map.assortment_problem:
def solve(**kwargs):
    import time
    import math

    start_time = time.time()
    deadline = start_time + 8.5

    m = int(kwargs.get("m", len(kwargs.get("pieces", []))))
    stocks = kwargs.get("stocks", [])
    pieces = kwargs.get("pieces", [])

    nstocks = len(stocks)

    def stock_area(t):
        return float(stocks[t]["length"]) * float(stocks[t]["width"])

    def piece_area(i):
        return float(pieces[i]["length"]) * float(pieces[i]["width"])

    def fits_in_stock(piece_idx, stock_idx):
        pl = float(pieces[piece_idx]["length"])
        pw = float(pieces[piece_idx]["width"])
        sl = float(stocks[stock_idx]["length"])
        sw = float(stocks[stock_idx]["width"])
        return (pl <= sl + 1e-9 and pw <= sw + 1e-9) or (pw <= sl + 1e-9 and pl <= sw + 1e-9)

    def rect_contains(a, b):
        return (a[0] <= b[0] + 1e-9 and a[1] <= b[1] + 1e-9 and
                a[0] + a[2] >= b[0] + b[2] - 1e-9 and
                a[1] + a[3] >= b[1] + b[3] - 1e-9)

    def prune_free(free_rects):
        res = []
        for i, r in enumerate(free_rects):
            if r[2] <= 1e-9 or r[3] <= 1e-9:
                continue
            contained = False
            for j, s in enumerate(free_rects):
                if i != j and rect_contains(s, r):
                    contained = True
                    break
            if not contained:
                res.append(r)
        return res

    def split_free_rect(f, px, py, pw, ph):
        fx, fy, fw, fh = f
        if px >= fx + fw - 1e-9 or px + pw <= fx + 1e-9 or py >= fy + fh - 1e-9 or py + ph <= fy + 1e-9:
            return [f]

        out = []
        if px > fx + 1e-9:
            out.append((fx, fy, px - fx, fh))
        if px + pw < fx + fw - 1e-9:
            out.append((px + pw, fy, fx + fw - (px + pw), fh))
        if py > fy + 1e-9:
            out.append((fx, fy, fw, py - fy))
        if py + ph < fy + fh - 1e-9:
            out.append((fx, py + ph, fw, fy + fh - (py + ph)))
        return out

    def clone_bins(bins):
        nb = []
        for b in bins:
            nb.append({
                "stock_type": b["stock_type"],
                "free": list(b["free"]),
                "placements": [dict(p) for p in b["placements"]],
                "used": b["used"]
            })
        return nb

    def try_place_in_bin(bin_obj, piece_idx):
        pl0 = float(pieces[piece_idx]["length"])
        pw0 = float(pieces[piece_idx]["width"])

        best = None
        for ori in (0, 1):
            if ori == 0:
                pl, pw = pl0, pw0
            else:
                pl, pw = pw0, pl0

            for k, fr in enumerate(bin_obj["free"]):
                x, y, w, h = fr
                if pl <= w + 1e-9 and pw <= h + 1e-9:
                    score = (w * h - pl * pw, min(w - pl, h - pw), y, x)
                    if best is None or score < best[0]:
                        best = (score, x, y, pl, pw, ori)

        if best is None:
            return False

        _, x, y, pl, pw, ori = best
        new_free = []
        for fr in bin_obj["free"]:
            new_free.extend(split_free_rect(fr, x, y, pl, pw))
        bin_obj["free"] = prune_free(new_free)
        bin_obj["placements"].append({
            "piece": piece_idx + 1,
            "x": float(x),
            "y": float(y),
            "orientation": int(ori)
        })
        bin_obj["used"] += pl * pw
        return True

    def add_new_bin_and_place(bins, piece_idx, allowed):
        candidates = []
        for st in allowed:
            if fits_in_stock(piece_idx, st):
                candidates.append(st)
        if not candidates:
            return False

        candidates.sort(key=lambda s: stock_area(s))
        for st in candidates:
            b = {
                "stock_type": st,
                "free": [(0.0, 0.0, float(stocks[st]["length"]), float(stocks[st]["width"]))],
                "placements": [],
                "used": 0.0
            }
            if try_place_in_bin(b, piece_idx):
                bins.append(b)
                return True
        return False

    def add_piece_to_bins(bins, piece_idx, allowed):
        order = list(range(len(bins)))
        order.sort(key=lambda k: stock_area(bins[k]["stock_type"]) - bins[k]["used"])
        for k in order:
            if try_place_in_bin(bins[k], piece_idx):
                return True
        return add_new_bin_and_place(bins, piece_idx, allowed)

    def compute_obj(bins):
        total_stock = 0.0
        total_used = 0.0
        for b in bins:
            total_stock += stock_area(b["stock_type"])
            total_used += b["used"]
        if total_stock <= 1e-12:
            return 0.0
        val = (total_stock - total_used) / total_stock
        if val < 0 and val > -1e-8:
            val = 0.0
        return float(val)

    def pack_for_allowed(allowed):
        counts = [0] * m
        items = []
        for i in range(m):
            mn = int(pieces[i].get("min", 0))
            mx = int(pieces[i].get("max", mn))
            if mn > mx:
                return None, None
            for _ in range(mn):
                items.append(i)
            counts[i] = mn

        items.sort(key=lambda i: (piece_area(i), max(float(pieces[i]["length"]), float(pieces[i]["width"]))), reverse=True)

        bins = []
        for i in items:
            if time.time() > deadline:
                break
            if not any(fits_in_stock(i, st) for st in allowed):
                return None, None
            if not add_piece_to_bins(bins, i, allowed):
                return None, None

        improved = True
        while improved and time.time() < deadline:
            improved = False
            cur_obj = compute_obj(bins)
            best_trial = None
            best_obj = cur_obj

            cand = []
            for i in range(m):
                if counts[i] < int(pieces[i].get("max", counts[i])) and any(fits_in_stock(i, st) for st in allowed):
                    cand.append(i)
            cand.sort(key=lambda i: piece_area(i), reverse=True)

            for i in cand[:max(10, min(40, len(cand)))]:
                if time.time() > deadline:
                    break
                tb = clone_bins(bins)
                if add_piece_to_bins(tb, i, allowed):
                    obj = compute_obj(tb)
                    if obj < best_obj - 1e-10:
                        best_obj = obj
                        best_trial = (tb, i)

            if best_trial is not None:
                bins, pi = best_trial
                counts[pi] += 1
                improved = True

        return bins, counts

    allowed_sets = []
    for i in range(nstocks):
        allowed_sets.append((i,))
    for i in range(nstocks):
        for j in range(i + 1, nstocks):
            allowed_sets.append((i, j))

    def allowed_score(a):
        return (len(a), sum(stock_area(x) for x in a))
    allowed_sets.sort(key=allowed_score)

    best_bins = None
    best_obj = None

    for allowed in allowed_sets:
        if time.time() > deadline:
            break

        possible = True
        for i in range(m):
            if int(pieces[i].get("min", 0)) > 0 and not any(fits_in_stock(i, st) for st in allowed):
                possible = False
                break
        if not possible:
            continue

        bins, counts = pack_for_allowed(allowed)
        if bins is None:
            continue

        obj = compute_obj(bins)
        if best_obj is None or obj < best_obj - 1e-12:
            best_obj = obj
            best_bins = bins

    if best_bins is None:
        best_bins = []
        for st in range(nstocks):
            best_bins.append({
                "stock_type": st,
                "free": [(0.0, 0.0, float(stocks[st]["length"]), float(stocks[st]["width"]))],
                "placements": [],
                "used": 0.0
            })
            break
        best_obj = compute_obj(best_bins)

    placements_out = {}
    for idx, b in enumerate(best_bins, 1):
        placements_out[idx] = {
            "stock_type": int(b["stock_type"]) + 1,
            "placements": b["placements"]
        }

    if not placements_out and nstocks > 0:
        placements_out[1] = {
            "stock_type": 1,
            "placements": []
        }
        best_obj = 1.0

    return {
        "objective": float(best_obj if best_obj is not None else 0.0),
        "placements": placements_out
    }

task_solution_map.bin_packing___one_dimensional:
def solve(**kwargs):
    import time
    import random
    import math

    start_time = time.time()
    deadline = start_time + 9.2

    capacity = int(kwargs.get("bin_capacity"))
    items = list(kwargs.get("items", []))
    n = int(kwargs.get("num_items", len(items)))

    if n == 0:
        return {"num_bins": 0, "bins": []}

    indexed_items = [(items[i], i + 1) for i in range(n)]

    def best_fit(order):
        bins = []
        loads = []
        for size, idx in order:
            best_j = -1
            best_rem = capacity + 1
            for j, load in enumerate(loads):
                rem = capacity - load
                if size <= rem and rem - size < best_rem:
                    best_rem = rem - size
                    best_j = j
            if best_j == -1:
                bins.append([idx])
                loads.append(size)
            else:
                bins[best_j].append(idx)
                loads[best_j] += size
        return bins, loads

    def first_fit(order):
        bins = []
        loads = []
        for size, idx in order:
            placed = False
            for j, load in enumerate(loads):
                if load + size <= capacity:
                    bins[j].append(idx)
                    loads[j] += size
                    placed = True
                    break
            if not placed:
                bins.append([idx])
                loads.append(size)
        return bins, loads

    # Initial deterministic solutions.
    dec_order = sorted(indexed_items, key=lambda x: (-x[0], x[1]))
    inc_order = sorted(indexed_items, key=lambda x: (x[0], x[1]))

    best_bins, best_loads = best_fit(dec_order)
    for cand_bins, cand_loads in (
        first_fit(dec_order),
        best_fit(inc_order),
        first_fit(inc_order),
    ):
        if len(cand_bins) < len(best_bins):
            best_bins, best_loads = cand_bins, cand_loads

    total_size = sum(items)
    lower_bound = max((total_size + capacity - 1) // capacity, max(items) // capacity if items else 0)

    # Exact branch-and-bound for smaller instances.
    def exact_with_k(k):
        sorted_items = sorted([(items[i], i + 1) for i in range(n)], reverse=True)
        rem = [capacity] * k
        assign = [[] for _ in range(k)]
        calls = [0]

        # Simple suffix sum pruning.
        suffix = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            suffix[i] = suffix[i + 1] + sorted_items[i][0]

        def dfs(pos):
            calls[0] += 1
            if calls[0] & 2047 == 0:
                if time.time() > deadline:
                    raise TimeoutError
            if pos == n:
                return True
            if sum(rem) < suffix[pos]:
                return False

            size, idx = sorted_items[pos]
            seen_remainders = set()

            # Try tighter bins first.
            order_bins = sorted(range(k), key=lambda b: rem[b])
            for b in order_bins:
                if rem[b] < size:
                    continue
                if rem[b] in seen_remainders:
                    continue
                seen_remainders.add(rem[b])

                rem[b] -= size
                assign[b].append(idx)

                if dfs(pos + 1):
                    return True

                assign[b].pop()
                rem[b] += size

                # Symmetry: if item did not fit into an empty bin successfully,
                # no need to try other empty bins.
                if rem[b] == capacity:
                    break
            return False

        try:
            if dfs(0):
                return [bin_[:] for bin_ in assign if bin_]
        except TimeoutError:
            return None
        return None

    if n <= 55 and lower_bound < len(best_bins):
        k = lower_bound
        while k < len(best_bins) and time.time() < deadline:
            exact = exact_with_k(k)
            if exact is not None:
                best_bins = exact
                best_loads = [sum(items[i - 1] for i in b) for b in best_bins]
                break
            k += 1

    # Try to eliminate bins by redistributing their contents.
    def try_remove_one_bin(bins, loads):
        m = len(bins)
        if m <= lower_bound:
            return bins, loads, False

        candidate_order = sorted(range(m), key=lambda j: (loads[j], len(bins[j])))

        for rem_bin_idx in candidate_order:
            if time.time() > deadline:
                return bins, loads, False

            moving = [(items[idx - 1], idx) for idx in bins[rem_bin_idx]]
            moving.sort(reverse=True)

            new_bins = [bins[j][:] for j in range(m) if j != rem_bin_idx]
            new_loads = [loads[j] for j in range(m) if j != rem_bin_idx]
            spaces = [capacity - x for x in new_loads]

            # Quick necessary check.
            if sum(size for size, _ in moving) > sum(spaces):
                continue
            if moving and moving[0][0] > max(spaces, default=0):
                continue

            placement = []

            def dfs_move(pos):
                if pos == len(moving):
                    return True
                if (pos & 7) == 0 and time.time() > deadline:
                    raise TimeoutError

                size, idx = moving[pos]
                seen = set()
                order = sorted(range(len(spaces)), key=lambda b: spaces[b])
                for b in order:
                    if spaces[b] >= size and spaces[b] not in seen:
                        seen.add(spaces[b])
                        spaces[b] -= size
                        new_loads[b] += size
                        new_bins[b].append(idx)
                        placement.append((b, idx))
                        if dfs_move(pos + 1):
                            return True
                        placement.pop()
                        new_bins[b].pop()
                        new_loads[b] -= size
                        spaces[b] += size
                return False

            try:
                if dfs_move(0):
                    return new_bins, new_loads, True
            except TimeoutError:
                return bins, loads, False

        return bins, loads, False

    improved = True
    while improved and len(best_bins) > lower_bound and time.time() < deadline:
        best_bins, best_loads, improved = try_remove_one_bin(best_bins, best_loads)

    # Randomized multi-start with subsequent bin elimination.
    rng = random.Random(1234567 + n + capacity)
    while time.time() < deadline and len(best_bins) > lower_bound:
        if n <= 1:
            break

        # Randomized decreasing order: mostly by size, with mild perturbation.
        if rng.random() < 0.5:
            order = dec_order[:]
            block = max(2, int(math.sqrt(n)))
            for s in range(0, n, block):
                sub = order[s:s + block]
                rng.shuffle(sub)
                order[s:s + block] = sub
        else:
            order = indexed_items[:]
            order.sort(key=lambda x: (-(x[0] * (0.85 + 0.3 * rng.random())), rng.random()))

        cand_bins, cand_loads = best_fit(order)
        if len(cand_bins) <= len(best_bins):
            improved2 = True
            while improved2 and len(cand_bins) > lower_bound and time.time() < deadline:
                cand_bins, cand_loads, improved2 = try_remove_one_bin(cand_bins, cand_loads)
            if len(cand_bins) < len(best_bins):
                best_bins, best_loads = cand_bins, cand_loads

    # Final safety validation/repair fallback.
    seen = []
    valid = True
    for b in best_bins:
        load = 0
        for idx in b:
            if idx < 1 or idx > n:
                valid = False
            else:
                load += items[idx - 1]
                seen.append(idx)
        if load > capacity:
            valid = False
    if len(seen) != n or len(set(seen)) != n:
        valid = False

    if not valid:
        best_bins, best_loads = best_fit(dec_order)

    return {
        "num_bins": len(best_bins),
        "bins": best_bins
    }

task_solution_map.capacitated_warehouse_location:
def solve(**kwargs):
    import time
    import math
    import random

    start_time = time.time()
    deadline = start_time + 9.2

    m = int(kwargs["m"])
    n = int(kwargs["n"])
    warehouses = kwargs["warehouses"]
    customers = kwargs["customers"]

    caps = [float(w.get("capacity", 0.0)) for w in warehouses]
    fixed = [float(w.get("fixed_cost", 0.0)) for w in warehouses]
    demands = [float(c.get("demand", 0.0)) for c in customers]
    costs = [list(map(float, c.get("costs", [0.0] * m))) for c in customers]

    total_demand = sum(demands)
    total_capacity = sum(caps)

    assignments_zero = [[0.0] * m for _ in range(n)]

    if n == 0 or total_demand <= 1e-12:
        return {
            "total_cost": 0.0,
            "warehouse_open": [0] * m,
            "assignments": assignments_zero,
        }

    if m == 0 or total_capacity + 1e-9 < total_demand:
        return {
            "total_cost": 0.0,
            "warehouse_open": [0] * m,
            "assignments": assignments_zero,
        }

    # Precompute warehouse order by cost for each customer.
    sorted_wh_by_customer = []
    customer_regret = []
    for i in range(n):
        order = sorted(range(m), key=lambda j: costs[i][j])
        sorted_wh_by_customer.append(order)
        if m >= 2:
            customer_regret.append(costs[i][order[1]] - costs[i][order[0]])
        elif m == 1:
            customer_regret.append(0.0)

    customer_order = sorted(range(n), key=lambda i: (-customer_regret[i], -demands[i]))

    avg_cost = []
    for j in range(m):
        s = 0.0
        for i in range(n):
            s += costs[i][j] * demands[i]
        avg_cost.append(s / total_demand if total_demand > 0 else 0.0)

    def evaluate(open_bool):
        rem = caps[:]
        opened = [1 if open_bool[j] and caps[j] > 1e-12 else 0 for j in range(m)]
        if sum(caps[j] for j in range(m) if opened[j]) + 1e-8 < total_demand:
            return None

        ass = [[0.0] * m for _ in range(n)]
        variable_cost = 0.0

        for i in customer_order:
            need = demands[i]
            if need <= 1e-12:
                continue
            for j in sorted_wh_by_customer[i]:
                if not opened[j]:
                    continue
                if rem[j] <= 1e-12:
                    continue
                x = need if need < rem[j] else rem[j]
                if x > 0.0:
                    ass[i][j] = x
                    rem[j] -= x
                    need -= x
                    variable_cost += x * costs[i][j]
                    if need <= 1e-8:
                        break
            if need > 1e-7:
                return None

        # Close warehouses that were selected but ended up unused.
        used = [0.0] * m
        for i in range(n):
            row = ass[i]
            for j in range(m):
                used[j] += row[j]
        for j in range(m):
            if used[j] <= 1e-9:
                opened[j] = 0

        total_cost = variable_cost + sum(fixed[j] for j in range(m) if opened[j])
        return total_cost, opened, ass

    best = None

    def consider(open_bool):
        nonlocal best
        if time.time() > deadline:
            return
        res = evaluate(open_bool)
        if res is not None and (best is None or res[0] < best[0]):
            best = res

    # Candidate 1: all warehouses.
    consider([1] * m)

    # Candidate prefixes under several scoring rules.
    min_fixed = min(fixed) if fixed else 0.0
    max_fixed = max(fixed) if fixed else 1.0
    min_avg = min(avg_cost) if avg_cost else 0.0
    max_avg = max(avg_cost) if avg_cost else 1.0
    fixed_scale = max(max_fixed - min_fixed, 1.0)
    avg_scale = max(max_avg - min_avg, 1.0)

    scoring_rules = []

    scoring_rules.append(lambda j: fixed[j] / (caps[j] + 1e-9))
    scoring_rules.append(lambda j: avg_cost[j])
    scoring_rules.append(lambda j: avg_cost[j] + fixed[j] / (caps[j] + 1e-9))
    scoring_rules.append(lambda j: (fixed[j] - min_fixed) / fixed_scale + (avg_cost[j] - min_avg) / avg_scale)
    scoring_rules.append(lambda j: 0.35 * (fixed[j] - min_fixed) / fixed_scale + (avg_cost[j] - min_avg) / avg_scale)
    scoring_rules.append(lambda j: (fixed[j] - min_fixed) / fixed_scale + 0.35 * (avg_cost[j] - min_avg) / avg_scale)
    scoring_rules.append(lambda j: fixed[j])
    scoring_rules.append(lambda j: -caps[j])

    for rule in scoring_rules:
        if time.time() > deadline:
            break
        order = sorted(range(m), key=rule)
        open_bool = [0] * m
        cap_sum = 0.0
        for j in order:
            open_bool[j] = 1
            cap_sum += caps[j]
            if cap_sum + 1e-9 >= total_demand:
                break
        consider(open_bool)

        # Also try adding a few cheapest-transport warehouses to this prefix.
        if time.time() <= deadline:
            ext = open_bool[:]
            for j in sorted(range(m), key=lambda x: avg_cost[x])[:max(1, min(m, 5))]:
                ext[j] = 1
            consider(ext)

    # Customer-driven candidate: open cheapest warehouses for largest demands until enough capacity.
    if time.time() <= deadline:
        open_bool = [0] * m
        cap_sum = 0.0
        cust_by_demand = sorted(range(n), key=lambda i: -demands[i])
        for i in cust_by_demand:
            for j in sorted_wh_by_customer[i][:min(m, 3)]:
                if not open_bool[j]:
                    open_bool[j] = 1
                    cap_sum += caps[j]
                    if cap_sum + 1e-9 >= total_demand:
                        break
            if cap_sum + 1e-9 >= total_demand:
                break
        if cap_sum + 1e-9 < total_demand:
            for j in sorted(range(m), key=lambda x: fixed[x] / (caps[x] + 1e-9)):
                if not open_bool[j]:
                    open_bool[j] = 1
                    cap_sum += caps[j]
                    if cap_sum + 1e-9 >= total_demand:
                        break
        consider(open_bool)

    # Local search: close costly warehouses if it improves the evaluated solution.
    improved = True
    while improved and time.time() <= deadline:
        improved = False
        if best is None:
            break
        current_open = best[1][:]
        close_order = sorted(
            [j for j in range(m) if current_open[j]],
            key=lambda j: (-fixed[j], avg_cost[j])
        )
        for j in close_order:
            if time.time() > deadline:
                break
            trial = current_open[:]
            trial[j] = 0
            if sum(caps[k] for k in range(m) if trial[k]) + 1e-9 < total_demand:
                continue
            before = best[0]
            consider(trial)
            if best is not None and best[0] + 1e-9 < before:
                current_open = best[1][:]
                improved = True
                break

    # Small add/drop refinement.
    if best is not None and time.time() <= deadline:
        base_open = best[1][:]
        closed = [j for j in range(m) if not base_open[j]]
        for add_j in sorted(closed, key=lambda j: avg_cost[j] + fixed[j] / (caps[j] + 1e-9))[:min(12, len(closed))]:
            if time.time() > deadline:
                break
            trial = base_open[:]
            trial[add_j] = 1
            consider(trial)

    if best is None:
        # Last-resort feasible construction with all warehouses.
        res = evaluate([1] * m)
        if res is None:
            return {
                "total_cost": 0.0,
                "warehouse_open": [0] * m,
                "assignments": assignments_zero,
            }
        best = res

    total_cost, warehouse_open, assignments = best

    # Numerical cleanup: remove tiny negatives/noise and recompute cost consistently.
    for i in range(n):
        for j in range(m):
            if abs(assignments[i][j]) < 1e-10:
                assignments[i][j] = 0.0

    used = [0.0] * m
    variable_cost = 0.0
    for i in range(n):
        for j in range(m):
            x = assignments[i][j]
            used[j] += x
            variable_cost += x * costs[i][j]

    warehouse_open = [1 if used[j] > 1e-9 else 0 for j in range(m)]
    total_cost = variable_cost + sum(fixed[j] for j in range(m) if warehouse_open[j])

    return {
        "total_cost": float(total_cost),
        "warehouse_open": warehouse_open,
        "assignments": assignments,
    }
